"""
ops_ledger_utils.py
A library of 30 small pure functions for processing operational ledger records.
"""

from typing import List, Dict, Any, Optional, Union

# Type alias for a ledger record
Record = Dict[str, Any]


def get_latency(record: Record) -> int:
    """Extract the latency_ms value from a record. Returns 0 if missing."""
    return record.get("latency_ms", 0)


def get_shard(record: Record) -> int:
    """Extract the shard ID from a record. Returns -1 if missing."""
    return record.get("shard", -1)


def get_state(record: Record) -> str:
    """Extract the state string from a record. Returns 'unknown' if missing."""
    return record.get("state", "unknown")


def is_ok(record: Record) -> bool:
    """Check if the record state is 'ok'."""
    return get_state(record) == "ok"


def is_error(record: Record) -> bool:
    """Check if the record state is not 'ok'."""
    return get_state(record) != "ok"


def filter_by_shard(records: List[Record], shard_id: int) -> List[Record]:
    """Filter records to only those belonging to a specific shard."""
    return [r for r in records if get_shard(r) == shard_id]


def filter_by_state(records: List[Record], state: str) -> List[Record]:
    """Filter records to only those with a specific state."""
    return [r for r in records if get_state(r) == state]


def filter_ok_records(records: List[Record]) -> List[Record]:
    """Filter records to only those with state 'ok'."""
    return [r for r in records if is_ok(r)]


def filter_error_records(records: List[Record]) -> List[Record]:
    """Filter records to only those with state not 'ok'."""
    return [r for r in records if is_error(r)]


def filter_by_latency_threshold(records: List[Record], threshold: int) -> List[Record]:
    """Filter records with latency strictly less than the threshold."""
    return [r for r in records if get_latency(r) < threshold]


